import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Quick Start","description":"The five-minute path — install the Sentinel panel addon, pair one node, watch the first detections arrive, and switch off dry-run when you are ready to enforce.","frontmatter":{"title":"Quick Start","description":"The five-minute path — install the Sentinel panel addon, pair one node, watch the first detections arrive, and switch off dry-run when you are ready to enforce."},"headers":[],"relativePath":"pterodactyl-sentinel/getting-started/quick-start.md","filePath":"pterodactyl-sentinel/getting-started/quick-start.md","lastUpdated":null}'),i={name:"pterodactyl-sentinel/getting-started/quick-start.md"};function o(l,e,r,p,d,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This is the fastest safe path from zero to a working Sentinel deployment: panel addon, one paired node, first events in the feed, then live enforcement. Budget about five minutes per node after the panel is installed.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Sentinel ships with <code>dry_run: true</code> by default. Detections are logged and reported, but <strong>nothing is killed, paused, stopped or suspended</strong> until you turn dry-run off. Keep it on while you tune, then disable it in step 5.</p></div><hr><h2 id="_1-install-the-panel-addon-2-minutes" tabindex="-1">1. Install the panel addon (2 minutes) <a class="header-anchor" href="#_1-install-the-panel-addon-2-minutes" aria-label="Permalink to &quot;1. Install the panel addon (2 minutes)&quot;">​</a></h2><p>Blueprint:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylsentinel-v1.0.0</span></span></code></pre></div><p>Or standalone:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PTERODACTYL_DIRECTORY=/var/www/pterodactyl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone/install.sh</span></span></code></pre></div><p>Open your panel&#39;s admin area — you should see <strong>Sentinel</strong> in the sidebar with the Dashboard, Detections, Nodes, Servers, Scans, Intel, Quarantine and Settings tabs.</p><h2 id="_2-create-a-node-token-30-seconds" tabindex="-1">2. Create a node token (30 seconds) <a class="header-anchor" href="#_2-create-a-node-token-30-seconds" aria-label="Permalink to &quot;2. Create a node token (30 seconds)&quot;">​</a></h2><p>Go to <strong>Sentinel → Nodes</strong>, find the Pterodactyl node you want to protect, and click <strong>Create token</strong>. Copy the 64-hex token — you will paste it into the node installer.</p><h2 id="_3-install-the-agent-on-the-node-2-minutes" tabindex="-1">3. Install the agent on the node (2 minutes) <a class="header-anchor" href="#_3-install-the-agent-on-the-node-2-minutes" aria-label="Permalink to &quot;3. Install the agent on the node (2 minutes)&quot;">​</a></h2><p>On the Wings node, as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-module/install.sh</span></span></code></pre></div><p>Answer the four prompts (panel URL, token, listen address <code>0.0.0.0</code>, port <code>8481</code>). The installer writes <code>/etc/sentinel/config.yaml</code> and <code>/etc/sentinel/token</code> (both <code>0600</code>), installs <code>sentinel-node.service</code>, starts it, and waits for registration.</p><p>Allow the panel to reach the node&#39;s API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">panel-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8481</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span></span></code></pre></div><p>Verify:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8481/api/v1/health</span></span></code></pre></div><p>Back in <strong>Sentinel → Nodes</strong>, the card flips to <strong>online</strong> with the agent version and a current last-seen time.</p><h2 id="_4-see-your-first-events-1-minute" tabindex="-1">4. See your first events (1 minute) <a class="header-anchor" href="#_4-see-your-first-events-1-minute" aria-label="Permalink to &quot;4. See your first events (1 minute)&quot;">​</a></h2><p>The agent is already scanning: process and connection detectors tick every 5 seconds, container scans every 3 minutes, volume scans every 15 minutes.</p><p>To see the detector output immediately, run a one-off pass on the node (no enforcement, nothing shipped):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    &quot;uuid&quot;: &quot;3f6c…&quot;,</span></span>
<span class="line"><span>    &quot;category&quot;: &quot;abuse&quot;,</span></span>
<span class="line"><span>    &quot;detector&quot;: &quot;abuse&quot;,</span></span>
<span class="line"><span>    &quot;severity&quot;: &quot;high&quot;,</span></span>
<span class="line"><span>    &quot;title&quot;: &quot;hosting abuse service detected&quot;,</span></span>
<span class="line"><span>    &quot;server_uuid&quot;: &quot;d8321c4e-…&quot;,</span></span>
<span class="line"><span>    &quot;process&quot;: &quot;/usr/bin/xmrig -o pool.minexmr.com:4444&quot;,</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>]</span></span>
<span class="line"><span>1 finding(s)</span></span></code></pre></div><p>Live detections flow to <strong>Sentinel → Detections</strong> within seconds, attributed to the exact server. The Dashboard tiles update on the next page load.</p><h2 id="_5-go-live-disable-dry-run" tabindex="-1">5. Go live: disable dry-run <a class="header-anchor" href="#_5-go-live-disable-dry-run" aria-label="Permalink to &quot;5. Go live: disable dry-run&quot;">​</a></h2><p>When you are comfortable with what Sentinel flags on your fleet:</p><ol><li>Open <strong>Sentinel → Settings → General</strong>.</li><li>Set <strong>Dry run</strong> to off and save.</li><li>The panel bumps <code>config_version</code> and pushes the new config to every online node; each node applies it atomically and confirms in <strong>Nodes → config version</strong>.</li></ol><p>Enforcement now follows the built-in rules: miners and abuse tooling at high severity get their processes killed; critical detections stop the container and suspend the server (panel-side, via <code>SuspensionService</code>); malware is quarantined. Review and adjust the policy under <strong>Settings → Enforcement Rules</strong> before or after going live.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Tune thresholds per detector: <a href="./../configuration/reference">Configuration Reference</a>.</li><li>Learn every tab: <a href="./../user-guide/admin-panel">Admin Panel</a>.</li><li>Wire up Discord/webhook/email alerts: <a href="./../user-guide/webhooks">Webhooks &amp; Alerts</a>.</li><li>Understand the pipeline: <a href="./../architecture/overview">Architecture</a>.</li></ul>`,34)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
